mapper.select:
select
from training, activity where training.activity_num = activity.activity_num and training.training_isdeleted = 0 and activity.activity_isdeleted = 0 and activity.organization_num = #{organizationNum,jdbcType=INTEGER}
and training.activity_num = #{activityNum,jdbcType=INTEGER}
order by training.training_begintime desc, training.training_num desc
